/* @lc app=leetcode id=3446 lang=kotlin */ class Solution { fun sortMatrix(grid: Array<IntArray>): Array<IntArray> = grid.size.let { n -> Array(n) { IntArray(n) }.also { res -> (-(n - 1)..n - 1).forEach { d -> (0 until n).filter { i -> i - d in 0 until n }.map { i -> i to i - d }.let { cells -> cells.map { grid[it.first][it.second] }.sorted().let { v -> if (d >= 0) v.reversed() else v }.let { vals -> cells.zip(vals).forEach { (c, v) -> res[c.first][c.second] = v } } } } } } }